* Control Block
.control
  set wr_singlescale

  * 1. Operating Point Analysis
  op
  let power_static = -i(vdd) * 1.8
  print power_static
  print v(Vout) v(vp) v(vm) v(N003)

  * 2. AC Analysis for Frequency Response
  ac dec 100 10 1G
  let gain_db = vdb(Vout)
  let phase_deg = 180 / PI * cph(v(Vout))

  * Measure DC Gain (at 100 Hz)
  meas ac open_loop_dc_gain find gain_db at=100

  * Measure 3-dB frequency
  let gain_3db = open_loop_dc_gain - 3.0
  meas ac dominant_pole_frequency when gain_db=gain_3db fall=1

  * Measure Unity-Gain Frequency and Phase Margin
  meas ac unity_gain_frequency when gain_db=0 fall=1
  meas ac phase_at_unity find phase_deg when gain_db=0 fall=1
  let phase_margin = 180 + phase_at_unity
  print phase_margin

  * Calculate effective transconductance from fun: gm = 2 * pi * fun * CL
  let gm_ota = 2 * PI * unity_gain_frequency * 1e-12
  print gm_ota

  * 3. Transient Analysis for Slew Rate
  tran 0.1n 300n
  meas tran sr_rising trig v(Vout) val=0.8 rise=1 targ v(Vout) val=1.0 rise=1
  meas tran sr_falling trig v(Vout) val=1.0 fall=1 targ v(Vout) val=0.8 fall=1
  let slew_rate_rising = 0.2 / sr_rising * 1e-6
  let slew_rate_falling = 0.2 / sr_falling * 1e-6
  print slew_rate_rising slew_rate_falling

  quit
.endc
.end

